// ============================================================================
//  tb_act_scatter.v -- twn_act_scatter checked as a layout, one whole row per case.
//
//  For every (C, W, pack) in tb_act_scatter_cases.vh (generated by
//  gen_scatter_cases.py in this directory: every block, both ternary stages) the
//  testbench drives f(x, c) = (x*31 + c*17 + 101*(c>>7) + 5) mod 256 beat by
//  beat, collects the words the scatter writes into a row, and compares every
//  byte against f(x, c) from its position. Each case runs at two beat rates
//  (one beat per two cycles, and back to back as twn_fuse_array delivers them)
//  and the row end is requested with a one-cycle flush pulse, as twn_fuse_top
//  does with arr_done.
//  ROW_BITS is 128 (the width twn_fuse_top instantiates); `ifdef SCAT_ROW_1024
//  runs the 1024-bit case instead. The define is valueless on purpose, as xvlog
//  splits -d NAME=VALUE on the '='.
// ============================================================================
`timescale 1ns/1ps
`default_nettype none

module tb_act_scatter;
    // ROW_BITS: see the header.
`ifdef SCAT_ROW_1024
    localparam integer ROW_BITS = 1024;
`else
    localparam integer ROW_BITS = 128;
`endif
    localparam integer PIX      = 4;
    localparam integer OCMAX    = 4;
    localparam integer WB       = ROW_BITS / 8;
    `include "tb_act_scatter_cases.vh"

    reg clk = 1'b0, rst = 1'b1;
    always #2 clk = ~clk;

    reg  [9:0]  c_chan;
    reg  [2:0]  pack;
    reg         in_valid, flush;
    reg  [9:0]  ocg;
    reg  [PIX*OCMAX*8-1:0] in_data;
    wire        flush_done;
    wire [15:0] wr_word;
    wire        wr_en;
    wire [ROW_BITS-1:0] wr_data;

    twn_act_scatter #(.ROW_BITS(ROW_BITS), .PIX(PIX), .OCMAX(OCMAX)) DUT (
        .clk(clk), .rst(rst),
        .c_chan(c_chan), .pack(pack),
        .in_valid(in_valid), .ocg(ocg), .in_data(in_data),
        .wr_word(wr_word), .wr_en(wr_en), .wr_data(wr_data),
        .flush(flush), .flush_done(flush_done));

    // the row the scatter builds, and a mask of which bytes it wrote
    localparam integer MAXW = (256 * 960) / WB + 8;
    reg [ROW_BITS-1:0] row  [0:MAXW-1];
    reg                wrote[0:MAXW-1];
    integer nwr;
    always @(posedge clk) if (!rst && wr_en) begin
        row[wr_word]   = wr_data;
        wrote[wr_word] = 1'b1;
        nwr            = nwr + 1;
    end

    // The 101*(c>>7) term breaks the 256-period of c in the fill, so channel
    // chunks an even number of 128-channel segments apart do not alias.
    function [7:0] fill;
        input integer x;
        input integer c;
        begin fill = (x * 31 + c * 17 + 101 * (c >> 7) + 5) & 8'hFF; end
    endfunction

    integer fl_wait;
    integer errors = 0, checked = 0, ci, C, W, PK, nxg, nocg, g, o, cp, cc, x, ch, i, b;
    // Beat rate: rate 0 is one beat per two cycles; rate 1 is back to back, the
    // twn_fuse_array output rate, where a group's last beat can coincide with
    // the previous group's drain reading its last bank word.
    integer rate, err_rate [0:1];
    reg [7:0] want, got;

    initial begin
        in_valid = 1'b0; flush = 1'b0; ocg = 0; in_data = 0;
        c_chan = 0; pack = 1; nwr = 0;
        err_rate[0] = 0; err_rate[1] = 0;
        repeat (8) @(negedge clk);
        rst = 1'b0;
        @(negedge clk);

        for (rate = 0; rate < 2; rate = rate + 1)
        for (ci = 0; ci < NCASE; ci = ci + 1) begin
            C  = SC_C[ci*16 +: 16];
            W  = SC_W[ci*16 +: 16];
            PK = SC_P[ci*16 +: 16];
            c_chan = C[9:0]; pack = PK[2:0];
            for (i = 0; i < MAXW; i = i + 1) wrote[i] = 1'b0;
            // Reset between cases so base_w does not carry over from the previous row.
            rst = 1'b1; @(negedge clk); @(negedge clk); rst = 1'b0;
            @(negedge clk);

            nxg  = W / PIX;  if (nxg == 0) nxg = 1;
            nocg = C / PK;
            for (g = 0; g < nxg; g = g + 1)
                for (o = 0; o < nocg; o = o + 1) begin
                    for (cp = 0; cp < PIX; cp = cp + 1)
                        for (cc = 0; cc < OCMAX; cc = cc + 1) begin
                            x  = g * PIX + cp;
                            ch = o * PK + cc;
                            in_data[(cp*OCMAX + cc)*8 +: 8] =
                                (cc < PK) ? fill(x, ch) : 8'hEE;   // beyond pack: junk
                        end
                    ocg = o[9:0];
                    if (rate == 0) begin
                        @(negedge clk); in_valid = 1'b1;
                        @(negedge clk); in_valid = 1'b0;
                    end else begin
                        // back to back: the value is set here, one negedge after
                        // the previous beat was consumed, so it is stable across
                        // the next posedge and in_valid never drops between
                        // beats. This is twn_fuse_array's rate.
                        in_valid = 1'b1;
                        @(negedge clk);
                    end
                end
            in_valid = 1'b0;
            // ---- the row end: a one-cycle flush pulse right after the last beat,
            // while the drain is still running ----
            @(negedge clk); flush = 1'b1;
            @(negedge clk); flush = 1'b0;
            fl_wait = 0;
            while (!flush_done && fl_wait < 4000) begin
                @(negedge clk); fl_wait = fl_wait + 1;
            end
            if (!flush_done) begin
                errors = errors + 1; err_rate[rate] = err_rate[rate] + 1;
                $display("  [%0s] C %0d W %0d pack %0d: no flush_done %0d cycles after a one-cycle flush -- the request was dropped",
                         (rate == 0) ? "half rate" : "back to back", C, W, PK, fl_wait);
            end
            @(negedge clk);

            // every byte of the row, from its position
            for (x = 0; x < W; x = x + 1)
                for (ch = 0; ch < C; ch = ch + 1) begin
                    checked = checked + 1;
                    b    = x * C + ch;
                    want = fill(x, ch);
                    got  = wrote[b / WB] ? row[b / WB][(b % WB)*8 +: 8] : 8'hxx;
                    if (got !== want) begin
                        errors = errors + 1; err_rate[rate] = err_rate[rate] + 1;
                        if (err_rate[rate] <= 8)
                            $display("  [%0s] C=%0d W=%0d pack=%0d  x=%0d ch=%0d byte=%0d: got %02h want %02h",
                                     (rate == 0) ? "half rate" : "back to back",
                                     C, W, PK, x, ch, b, got, want);
                    end
                end
        end

        $display("  by beat rate: half rate %0d errors, BACK TO BACK %0d errors",
                 err_rate[0], err_rate[1]);
        $display("=== tb_act_scatter: %0d cases x 2 rates, %0d words written, %0d bytes, %0d errors, %s ===",
                 NCASE, nwr, checked, errors,
                 (errors == 0 && checked > 0) ? "ALL PASS" : "FAIL");
        $finish;
    end

    initial begin
        #900_000_000;
        $display("=== tb_act_scatter: TIMEOUT after %0d bytes, %0d errors ===", checked, errors);
        $finish;
    end
endmodule
`default_nettype wire
